import { spawn } from 'node:child_process';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

// asyncRewake (CC hooks reference; measured on 2.1.248 and 2.1.251 with a
// nonce-bearing PostToolUse hook): an async hook's block verdict is inert and
// its JSON arrives on the next turn, but a hook that exits 2 under
// "asyncRewake": true wakes Claude immediately with its stderr. run-hook.mjs
// therefore maps continue:false to exit 2 + stderr when, and only when, the
// entry passes --rewake. Three cases: the mapping fires, it stays silent on a
// non-blocking result, and it stays silent without the flag (so a sync hook
// keeps its JSON-only contract).

const RUN_HOOK = join(__dirname, '../../../bin/run-hook.mjs');
const HOOK = 'pretool/bash/dangerous-command-blocker';
// Assembled so the literal never appears in a file a Bash guard might scan.
const CATASTROPHIC = ['rm', '-rf', '/'].join(' ');

function payload(command: string): string {
  return JSON.stringify({
    hook_event_name: 'PreToolUse',
    session_id: '00000000-0000-4000-8000-000000000000',
    cwd: '/tmp',
    tool_name: 'Bash',
    tool_input: { command },
  });
}

function run(args: string[], command: string): Promise<{ code: number | null; stdout: string; stderr: string }> {
  return new Promise((resolve) => {
    const child = spawn('node', [RUN_HOOK, HOOK, ...args], {
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env, CLAUDE_PROJECT_DIR: '/tmp' },
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (c) => { stdout += String(c); });
    child.stderr.on('data', (c) => { stderr += String(c); });
    child.on('close', (code) => resolve({ code, stdout, stderr }));
    child.stdin.end(payload(command));
  });
}

function lastJson(stdout: string): { continue?: boolean } {
  const line = stdout.trim().split('\n').filter((l) => l.startsWith('{')).pop();
  return line ? JSON.parse(line) : {};
}

describe('run-hook.mjs --rewake (asyncRewake exit-2 mapping)', () => {
  it('exits 2 and repeats the stopReason on stderr when the hook blocks', async () => {
    const r = await run(['--rewake'], CATASTROPHIC);
    expect(r.code).toBe(2);
    expect(r.stderr).toMatch(/\[pretool\/bash\/dangerous-command-blocker\] Command matches dangerous pattern/);
    expect(lastJson(r.stdout).continue).toBe(false);
  }, 20000);

  it('exits 0 with no rewake line when the hook does not block', async () => {
    const r = await run(['--rewake'], 'echo hi');
    expect(r.code).toBe(0);
    expect(r.stderr).not.toMatch(/\[pretool\/bash\/dangerous-command-blocker\]/);
  }, 20000);

  it('exits 0 on a block without the flag (sync contract unchanged)', async () => {
    const r = await run([], CATASTROPHIC);
    expect(r.code).toBe(0);
    expect(lastJson(r.stdout).continue).toBe(false);
    expect(r.stderr).not.toMatch(/\[pretool\/bash\/dangerous-command-blocker\]/);
  }, 20000);
});
